package com.medisphere.milestone3.controller;
import com.medisphere.milestone3.dto.*;import com.medisphere.milestone3.service.AlertFatigueService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/alerts") @CrossOrigin(origins="*") public class AlertController{private final AlertFatigueService s;public AlertController(AlertFatigueService s){this.s=s;}@PostMapping public AlertResponse process(@Valid @RequestBody AlertRequest r){return s.process(r);}@GetMapping("/recent") public List<AlertResponse> recent(){return s.recent();}@GetMapping("/metrics") public AlertMetricsResponse metrics(){return s.metrics();}@GetMapping("/{id}") public AlertResponse get(@PathVariable Long id){return s.get(id);}@PostMapping("/{id}/acknowledge") public AlertResponse ack(@PathVariable Long id){return s.acknowledge(id);}@PostMapping("/{id}/escalate") public AlertResponse esc(@PathVariable Long id){return s.escalate(id);}}
